/**
 * Booking-for-later slots, platform-free (the websites' SlotPicker and the apps
 * both read this): each day from `days` ahead, half-hours from `fromHour` to
 * `toHour`, never sooner than `leadMinutes` from now.
 */
const DAY_MS = 86400000;

export const startOfDay = (d) => { const x = new Date(d); x.setHours(0, 0, 0, 0); return x; };

export const slotLabel = (d) => new Date(d).toLocaleString('en-IN', { weekday: 'short', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' });

/** [{ day: Date, times: Date[] }], days with no time left dropped. */
export function buildSlots({ days = 7, leadMinutes = 60, fromHour = 8, toHour = 20 } = {}) {
  const earliest = Date.now() + leadMinutes * 60000;
  const out = [];
  for (let d = 0; d < days; d += 1) {
    const day = startOfDay(Date.now() + d * DAY_MS);
    const times = [];
    for (let m = fromHour * 60; m <= toHour * 60; m += 30) {
      const t = new Date(day.getTime() + m * 60000);
      if (t.getTime() >= earliest) times.push(t);
    }
    if (times.length) out.push({ day, times });
  }
  return out;
}

/** "Today", else the short weekday. */
export const dayName = (day) => (startOfDay(new Date()).getTime() === startOfDay(day).getTime() ? 'Today' : new Date(day).toLocaleDateString('en-IN', { weekday: 'short' }));
